@import"https://fonts.googleapis.com/css2?family=Noto+Serif+JP:wght@400;600;700&family=Shippori+Mincho:wght@400;600;700&display=swap";:root{--paper:#fffaf4;--ink:#342b2a;--red:#b33939;--blue:#6676a9;--bamboo:#718b75;--line:#d9c9b7;--shadow:0 10px 26px #6d4d3a18}*{box-sizing:border-box}body{margin:0;background:rgba(0,0,0,0);color:var(--ink);font-family:"Noto Serif JP","Songti SC",serif}.reader{position:relative;width:100%;max-width:880px;margin:auto;padding:18px;background:var(--paper);border:1px solid var(--line);box-shadow:var(--shadow);overflow:hidden;font-size:var(--reader-size);transition:.35s}.reader::before{content:"";position:absolute;inset:0;pointer-events:none;opacity:.2;background-image:radial-gradient(#b9957d 0.5px, transparent 0.5px);background-size:7px 7px}.reader>*{position:relative;z-index:1}.masthead{display:flex;gap:14px;align-items:center;border-bottom:1px solid var(--line);padding-bottom:15px}.brand-mark{font-size:40px;color:var(--red);font-family:serif}.eyebrow{margin:0;color:var(--red);font:600 .65em/1.4 "Shippori Mincho";letter-spacing:.18em}.masthead h1{margin:3px 0;font:700 1.45em "Shippori Mincho"}.subtitle{margin:0;color:#88766c;font-size:.75em}.header-actions{margin-left:auto;display:flex;gap:6px;align-self:flex-start}.header-actions button,.segmented button,.control select,.draw-button{border:1px solid var(--line);background:#fffdf9;color:inherit;padding:7px 10px;font:inherit;font-size:.7em;cursor:pointer}.header-actions button.on{color:var(--red);border-color:var(--red)}.panel{background:#fffdf9;border:1px solid var(--line);box-shadow:0 4px 14px rgba(109,77,58,.0431372549)}.console{display:flex;gap:14px;align-items:center;padding:10px;margin:15px 0}.control{display:flex;align-items:center;gap:7px;font-size:.72em}.segmented{display:flex}.segmented button.selected{background:var(--red);color:#fff;border-color:var(--red)}.slider-control{margin-left:auto;font-size:.72em;display:flex;align-items:center;gap:8px}.slider-control input{accent-color:var(--red);width:85px}.status-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.character-card,.world-card{padding:14px}.fox-crest{float:left;width:42px;height:42px;margin-right:10px;border:1px solid var(--red);border-radius:50%;display:grid;place-items:center;color:var(--red);font:700 1.4em serif}.card-heading{display:flex;justify-content:space-between;gap:8px;font-size:.8em}.card-heading strong{color:var(--red);font-size:.8em}.thought{clear:both;margin:14px 0 10px;color:#796761;font-size:.82em;font-style:italic;line-height:1.6}.bond{display:flex;align-items:center;gap:8px;font-size:.72em}.track{height:6px;flex:1;background:#eadfd3;border-radius:5px;overflow:hidden}.track i{display:block;height:100%;background:linear-gradient(90deg, #d48b82, var(--red));border-radius:5px}.world-facts{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0;color:#6d675d;font-size:.7em}.outfit{margin:0;color:#796761;font-size:.76em;line-height:1.6}.story{margin-top:15px;padding:28px clamp(18px,5vw,55px);background:linear-gradient(100deg, #fffdf9, #fffaf4)}.story-ribbon{display:inline-block;color:var(--red);border-bottom:2px solid #d49a8e;padding-bottom:4px;margin-bottom:14px;font-size:.75em}.story-body{font-size:1em;line-height:2.15}.story-body p{margin:0 0 1em;text-indent:2em}.story-body .dialogue{display:inline-flex;flex-direction:column;line-height:1.35;color:var(--red);font-weight:600}.story-body .dialogue small{font-size:.68em;color:#8b7e7a;font-weight:400}.story-body .dialogue em{font-style:normal}.gloss{border-bottom:1px dashed var(--blue);color:#4f608d;cursor:help}.gloss sup{font-size:.6em;color:#c07a8e}.omikuji{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-top:15px;padding:15px 20px}.omikuji h2{margin:4px 0;font:600 1.15em "Shippori Mincho"}.omikuji p:not(.eyebrow){margin:4px 0 12px;font-size:.76em;color:#786d66}.draw-button{background:var(--red);color:#fff;border-color:var(--red)}.fortune-slip{width:74px;height:108px;background:#f8e6b8;b